export type IconName = keyof typeof ICON_PATHS

// The raw glyph, for markup built outside React (e.g. Leaflet marker HTML). Draw it in the same 14×14 viewBox.
export const iconPath = (name: IconName) => ICON_PATHS[name]

type IconProps = {
  name: IconName
  fill: string
  className?: string
}

export function Icon({ name, fill, className }: IconProps) {
  return (
    <svg
      viewBox="0 0 13.99993896484375 14"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-hidden="true"
    >
      <path d={ICON_PATHS[name]} fill={fill} />
    </svg>
  )
}
